-- STEP 9: projection-based inventory risk; no average-usage stockout calculation.
create table if not exists core.lead_time_policy(item_id text not null,supplier_id text,confirmed_lead_time_days numeric,effective_from date not null default current_date,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),primary key(item_id,effective_from));
create table if not exists core.lead_time_policy_history(id uuid primary key default gen_random_uuid(),item_id text,supplier_id text,before_value jsonb,after_value jsonb,changed_by uuid references auth.users(id),changed_at timestamptz not null default now());
create table if not exists core.soft_allocation(item_id text not null,allocation_date date not null,qty numeric not null,source_record_id text,primary key(item_id,allocation_date,source_record_id));
create or replace view analytics.v_effective_lead_time with(security_invoker=true) as select p.item_id,p.supplier_id,p.confirmed_lead_time_days,lg.p80_days as actual_p80,coalesce(p.confirmed_lead_time_days,lg.p80_days) effective_lead_time_days,case when p.confirmed_lead_time_days is not null then 'ADMIN_CONFIRMED' when lg.p80_days is not null then 'ACTUAL_P80' else 'NO_LEADTIME' end source from core.lead_time_policy p full join analytics.v_leadtime_gap lg on lg.supplier_id=p.supplier_id;
create or replace view analytics.v_inventory_projection with(security_invoker=true) as with champ as(select distinct on(item_id) item_id,champion_model_id from analytics.v_champion_model order by item_id,selected_at desc), fc as(select r.item_id,r.period,r.predicted_qty from analytics.v_forecast_result r join champ c on c.item_id=r.item_id and c.champion_model_id=r.model_id), inv as(select to_jsonb(i)->>'품목코드' item_id,max((to_jsonb(i)->>'현재고')::numeric) beginning_inventory from raw.inventory i group by 1), po as(select to_jsonb(p)->>'품목코드' item_id,(to_jsonb(p)->>'납기예정일')::date period,sum((to_jsonb(p)->>'발주수량')::numeric) qty from raw.purchase_order p group by 1,2), so as(select item_id,date_trunc('month',requested_date)::date period,sum(qty) qty from raw.sales_order where status='CONFIRMED' group by 1,2), sa as(select item_id,date_trunc('month',allocation_date)::date period,sum(qty) qty from core.soft_allocation group by 1,2), base as(select f.*,inv.beginning_inventory,coalesce(po.qty,0) receipts,coalesce(so.qty,0) confirmed_sales,coalesce(sa.qty,0) soft_allocation from fc f left join inv using(item_id) left join po on po.item_id=f.item_id and date_trunc('month',po.period)=f.period left join so on so.item_id=f.item_id and so.period=f.period left join sa on sa.item_id=f.item_id and sa.period=f.period) select *,case when beginning_inventory is null then null else beginning_inventory+sum(receipts-confirmed_sales-soft_allocation-predicted_qty) over(partition by item_id order by period) end ending_projected_inventory,case when beginning_inventory is null then 'NO_INVENTORY_DATA' when predicted_qty is null then 'NO_FORECAST' end reason_code from base;
create or replace view analytics.v_stockout_risk with(security_invoker=true) as with p as(select *,min(period) filter(where ending_projected_inventory<=0) over(partition by item_id) stockout_period from analytics.v_inventory_projection), x as(select distinct on(item_id) p.*,l.effective_lead_time_days from p left join analytics.v_effective_lead_time l using(item_id) order by item_id,period) select item_id,stockout_period,ending_projected_inventory,effective_lead_time_days,case when reason_code is not null then 'CALCULATION_UNAVAILABLE' when effective_lead_time_days is null then 'CALCULATION_UNAVAILABLE' when stockout_period is null then 'SAFE' when stockout_period < (current_date+effective_lead_time_days)::date then 'CRITICAL' else 'WARNING' end risk_status,coalesce(reason_code,case when effective_lead_time_days is null then 'NO_LEADTIME' end) reason_code from x;
